\label{TheoA}
Let $\mathfrak{g}_{\mathbb{C}} \in\{\mathfrak{sl}_N,\mathfrak{so}_N,\mathfrak{sp}_N\}$ be a classical complex simple Lie algebra, with Borel subalgebra $\mathfrak{b}_{\mathbb{C}}$ and associated set of simple roots labeled by a set $I$.  Let $\hbar\in \mathbb{R}^{\times}$ and put $q = e^{-\pi i \hbar}$. 

There exists a locally compact quantum group $(L_{\hbar}(B),\Delta)$, with the von Neumann algebra $L_{\hbar}(B)$ generated by affiliated positive (unbounded) operators $\{\mathbf{E}_i,\mathbf{K}_i\mid i\in I\}$, such that the following hold: 
\begin{enumerate}
\item The operators $\mathbf{E}_i,\mathbf{K}_i$ satisfy 
\begin{equation}\label{EqCoprodForm}
\Delta(\mathbf{K}_i) = \mathbf{K}_i\otimes \mathbf{K}_i,\qquad \Delta(\mathbf{E}_i) = \mathbf{E}_i \otimes 1 \boxplus \mathbf{K}_i \otimes \mathbf{E}_i,\qquad \forall i\in I,
\end{equation}
where $\boxplus$ is the \emph{form sum} of positive operators. 
\item When $q$ is not a root of unity, there exists a concrete faithful normal $*$-representation $L_{\hbar}(B) \subseteq \mathcal{B}(\mathcal{H})$ on a Hilbert space $\mathcal{H}$, and a dense subspace $\mathscr{D} \subseteq \mathcal{H}$ in the common domain of, and stable under, the generators $\mathbf{E}_i,\mathbf{K}_i$, such that 
\[
\pi: U_q(\mathfrak{b}_{\mathbb{C}}) \rightarrow \operatorname{\mathrm{End}}(\mathscr{D}),\qquad K_i \mapsto  (\mathbf{K}_i)_{\mid \mathscr{D}},\quad E_i \mapsto  (\mathbf{E}_i)_{\mid \mathscr{D}}
\]
makes $\mathscr{D}$ into a faithful $U_q(\mathfrak{b}_{\mathbb{C}})$-module, with $U_q(\mathfrak{b}_{\mathbb{C}}) \subseteq U_q(\mathfrak{g}_{\mathbb{C}})$ the Borel part of the Drinfeld--Jimbo quantized enveloping algebra of $\mathfrak{g}_{\mathbb{C}}$ (see e.g.\ \cite{Jan96} for definitions).
\end{enumerate}

A \emph{(formal) word} $\mathbf{i}$ in $I$ consists of a finite totally ordered set 
\begin{equation}\label{EqTotal1}
J = J(\mathbf{i}) = \{a\} = \{a_1<a_2<\dotsb<a_N\}
\end{equation}
together with a map 
\begin{equation}\label{EqTotal2}
\mathbf{i}: J \rightarrow I,\qquad a \mapsto \mathbf{i}(a) = i_a.
\end{equation}
We refer to the cardinality $N$ of $J$ as the \emph{length} $\ell(\mathbf{i})$ of the word $\mathbf{i}$.  

We call $\mathbf{i}$ \emph{surjective} if \eqref{EqTotal2} is surjective.

If $\mathbf{i} = (i_1,i_2,\ldots,i_N)$ is a word in $I$, we refer to 
\begin{equation}\label{EqWordWeyl}
w_{\mathbf{i}} = s_{i_1}\ldots s_{i_N} \in W(I)
\end{equation}
as the associated Coxeter group element. We then call $\mathbf{i}$ \emph{reduced} if $\ell(\mathbf{i}) = \ell(w_{\mathbf{i}})$.

We call a word $\mathbf{i}$ \emph{integrable} if equality holds in \eqref{EqInclBorelInf}, i.e.\ when 
\begin{equation}\label{EqEqBorelInf}
L_{\hbar}(N(\mathbf{i})) = L_{\hbar}(\mathfrak{n}(\mathbf{i})).
\end{equation}

\label{DefFullExch}
We call two words $\mathbf{i},\mathbf{i}'$ \emph{equivalent} if there exists an $\mathfrak{h}'$-equivariant $*$-isomorphism 
\begin{equation}\label{EqPhiEquivWord}
\Phi: L_{\hbar}(\mathfrak{n}(\mathbf{i})) \rightarrow L_{\hbar}(\mathfrak{n}(\mathbf{i}')) \qquad \textrm{with}\qquad 
\Phi(\mathbf{E}_i(\mathbf{i})) = \mathbf{E}_i(\mathbf{i}'),\qquad \forall i\in I.
\end{equation}

We  call a word $\mathbf{i}$ \emph{fully exchangeable} if for each $i \in I$ there exists an equivalent word $\mathbf{i}'$ with $i_1' = i$.

\label{TheoClassicalIntFull}
Let $I$ be a classical Cartan datum, and $\mathbf{i}$ a word over $I$. 
\begin{enumerate}
\item If $\mathbf{i}$ is reduced, then $\mathbf{i}$ is integrable.
\item If $w_{\mathbf{i}} = w_0$, then $\mathbf{i}$ is fully exchangeable.
\end{enumerate}

\label{DefLCQGFormal}
A \emph{von Neumann bialgebra} is a von Neumann algebra $M$ equipped with a faithful, normal unital $*$-homomorphism
\[
\Delta: M \rightarrow M\bar{\otimes} M
\]
satisfying the \emph{coassociativity} condition
\begin{equation}\label{EqCoass}
(\Delta\otimes \operatorname{\mathrm{id}})\Delta = (\operatorname{\mathrm{id}}\otimes \Delta)\Delta. 
\end{equation}

It is called a \emph{locally compact quantum group} (in the von Neumann algebraic setting \cite{KV03}) if there exist nsf (= normal, semi-finite, faithful) weights 
\[
\varphi,\psi: M^+ \rightarrow [0,\infty],
\]
referred to as \emph{Haar weights}, satisfying respectively the \emph{left invariance} and the \emph{right invariance} conditions with respect to $\Delta$: 
\begin{equation}\label{EqLeftInvariance}
\varphi((\omega\otimes \operatorname{\mathrm{id}})\Delta(x)) = \varphi(x),\qquad \forall x\in M^+,\omega \in S_*(M),
\end{equation}
\begin{equation}\label{EqRightInvariance}
\psi((\operatorname{\mathrm{id}}\otimes \omega)\Delta(x)) = \psi(x),\qquad \forall x\in M^+,\omega \in S_*(M).
\end{equation}

Note that in this algebraic setting, the $K_i,X_a$ satisfy the (universal) commutation relations
\begin{equation}\label{EqAlgebraicCommGen}
K_iK_j = K_jK_i,\qquad X_b X_a = q^{\langle i_a,i_b\rangle}X_aX_b,\qquad b>a,\qquad K_iX_a = q^{\langle i,i_a\rangle} X_aK_i,\qquad i,j\in I,a,b\in J. 
\end{equation}

Let $\hbar\in\mathbb{R}$. Let $\mathbf{A},\mathbf{B}$ be positive operators on a Hilbert space. We say that $\mathbf{A},\mathbf{B}$ \emph{$\hbar$-commute}, or that $(\mathbf{A},\mathbf{B})$ forms an $\hbar$-commuting pair, if
\begin{equation}\label{EqSkewComm}
\mathbf{A}^{it} \mathbf{B}^{is} = e^{2\pi i  \hbar st}\mathbf{B}^{is}\mathbf{A}^{it},\qquad \forall s,t\in \mathbb{R}. 
\end{equation}

\label{LemDistr}
Assume $\mathbf{A},\mathbf{B},\mathbf{C}$ are positive operators on a Hilbert space, with $\mathbf{B},\mathbf{C}$ form-summable, with $\mathbf{A},\mathbf{B}$ skew-commuting and with $\mathbf{A},\mathbf{C}$ skew-commuting. Assume that $\hbar(\mathbf{A},\mathbf{B}) = \hbar(\mathbf{A},\mathbf{C}) = \hbar\in \mathbb{R}$. Then $\mathbf{A}$ and $\mathbf{B}\boxplus \mathbf{C}$ $\hbar$-commute, while  $\mathbf{A}\star\mathbf{B}$ and $\mathbf{A}\star \mathbf{C}$ are form-summable, and we have the identity 
\begin{equation}\label{EqCompDist}
\mathbf{A}\star(\mathbf{B}\boxplus \mathbf{C}) = \mathbf{A}\star\mathbf{B}\boxplus \mathbf{A}\star \mathbf{C}. 
\end{equation}

\label{DefHeisComm}
Let $\mathbf{E},\mathbf{F}$ be positive operators on a Hilbert space $\mathcal{H}$. 

We say that $\mathbf{E}$ and $\mathbf{F}$ \emph{quantum Heisenberg commute} at $\hbar$ if there exists a positive operator $\mathbf{L}$ on $\mathcal{H}$ such that $(\mathbf{L},\mathbf{F})$ and $(\mathbf{E},\mathbf{L})$ are $\hbar$-commuting, and such that \begin{equation}\label{EqPentagon}
F_{\hbar}(s\mathbf{F})F_{\hbar}(t\mathbf{E}) = F_{\hbar}(t\mathbf{E})F_{\hbar}(st\mathbf{L})F_{\hbar}(s\mathbf{F}),\qquad \forall s,t\geq0.
\end{equation}

We then also say that $\mathbf{E}$ and $\mathbf{F}$ \emph{Heisenberg $\mathbf{L}$-commute} at $\hbar$, or that $(\mathbf{E},\mathbf{F})$ form a \emph{Heisenberg $\mathbf{L}$-pair} at $\hbar$.

\label{TheoHeisPent}
Assume $\mathbf{L},\mathbf{E},\mathbf{F}$ are positive operators such that $(\mathbf{L},\mathbf{F})$ and $(\mathbf{E},\mathbf{L})$ are $\hbar$-commuting. Then the following are equivalent: 
\begin{enumerate}
\item $(\mathbf{E},\mathbf{F})$ form a Heisenberg $\mathbf{L}$-pair at $\hbar$.
\item We have
\begin{equation}\label{EqPentagonOr}
F_{\hbar}(\mathbf{E})^*\mathbf{F} F_{\hbar}(\mathbf{E}) = \mathbf{L} \boxplus \mathbf{F}.
\end{equation}
\item We have
\begin{equation}\label{EqPentagonOr2}
F_{\hbar}(\mathbf{F})\mathbf{E} F_{\hbar}(\mathbf{F})^* = \mathbf{L} \boxplus \mathbf{E}.
\end{equation}
\end{enumerate}

\label{LemDirSumSkew}
Let $W$ be a skew-symmetric space, and assume 
\begin{equation}\label{EqSkewDecompTriv}
W = V\oplus Z,\qquad \epsilon_{\mid Z\times Z} = 0.
\end{equation}
Then there exists a unique $*$-isomorphism 
\begin{equation}
Z \ltimes_{\gamma} L_{\hbar}(V)\cong L_{\hbar}(W),\quad \mathbf{q}(v) \mapsto \mathbf{q}(v),\quad \mathbf{q}(z) \mapsto \mathbf{q}(z),\qquad v\in V,z\in Z,
\end{equation}
where the action $\gamma$ of $Z$ on $L_{\hbar}(V)$ is uniquely determined through
\[
\gamma_z(\mathbf{q}(v)) =e^{-2\pi \hbar \epsilon(v,z)}\mathbf{q}(v),\qquad z\in Z,v\in V.
\]

More generally, for any direct sum $Z^T$ over a finite index set $T$ (with the direct sum skew-symmetric form), we denote $z_a$ for the copy of $z\in Z$ at position $a\in T$. We can then identify 
\begin{equation}\label{EqLongTens}
L_{\hbar}(Z^T) = \overline{\otimes}_T\mathcal{B}(L^2(\mathbb{R})),\qquad \mathbf{q}(z_a) = \mathbf{q}(z)_a = \left(\otimes_{b<a} 1\right) \otimes \mathbf{q}(z)\otimes \left(\otimes_{b>a} 1\right).
\end{equation}

\label{RemPresNonDeg} 
If $I$ is non-degenerate and $\mathbf{i}$ is surjective, we can extend \eqref{EqEmbSkewSymm} to an inclusion  of skew-symmetric spaces 
\[
\mathfrak{b}(\mathbf{i}) \subseteq Z^J,\qquad a \mapsto \left(\sum_{b<a} \langle i_a,i_b\rangle h_b\right)+ p_a,\qquad i \mapsto \sum_b \langle i,i_b\rangle h_b,\qquad a\in J,i\in I.
\]
It follows that, with the $\mathbf{k}_{\omega}$ as in \eqref{EqXVarCart}, we can then identify 
\begin{equation}
L_{\hbar}(\mathfrak{b}(\mathbf{i})) \cong \{\mathbf{k}_{\alpha_i},\mathbf{X}_a\mid i\in I,a\in J\}'' \subseteq \mathcal{B}(\mathcal{H}(\mathbf{i})),\qquad \mathbf{K}_i\mapsto \mathbf{k}_{\alpha_i}.  
\end{equation}

If $I'$ is the image of the word $\mathbf{i}$, we have a natural decomposition 
\begin{equation}\label{EqSplittingOff}
L_{\hbar}(\mathfrak{b}(\mathbf{i})) \cong L_{\hbar}(\mathfrak{b}(\mathbf{i}^{\mid I'})) \bar{\otimes} L(\mathbb{R}[I\setminus I']),
\end{equation}
where $\mathbf{i}^{\mid I'}$ is the corestriction of $\mathbf{i}$ to the codomain $I'$.

\label{DefRedHeisSpace}
Let $\mathbf{i}$ be a word over $I$. We define the \emph{(reduced) Heisenberg space} $\mathfrak{d} = \mathfrak{d}(\mathbf{i})$ as the direct sum vector space $\mathfrak{b}\oplus \mathfrak{h}'$, equipped with the unique skew-symmetric form $\epsilon$ extending $\epsilon$ on $\mathfrak{b}$ and $\mathfrak{h}'$, and with
\begin{equation}\label{EqPairHeis}
\epsilon(i,\omega) = \langle i,\omega\rangle/2,\qquad \epsilon(a,\omega) = \langle i_a,\omega\rangle/2,\qquad \forall i\in I,a\in J,\omega \in \mathfrak{h}'.  
\end{equation}
We then also put
\[
\mathfrak{b}' = \mathfrak{b}'(\mathbf{i}) = \mathfrak{n}(\mathbf{i})\oplus \mathfrak{h}'\subseteq \mathfrak{d}(\mathbf{i}). 
\]

\label{DefHeisDualOp}
Let $\mathbf{i}$ be a word over $I$. By a \emph{dual simple root operator} at $i\in I$, we mean a positive operator $\mathbf{F}_i$ affiliated to $L_{\hbar}(\mathfrak{d}(\mathbf{i}))$, satisfying the following conditions: 
\begin{enumerate}
\item\label{EqCond1} $\mathbf{K}_j$ and $\mathbf{F}_i$ strongly commute for all $j\in I$,
\item\label{EqCond2} $\mathbf{L}_j'$ and $\mathbf{F}_i$ form a $\delta_{ij}\hbar/2$-commuting pair, for all $j\in I$,
\item\label{EqCond3} $\mathbf{E}_j$ and $\mathbf{F}_i$ strongly commute for all $j\neq i$, 
\item\label{EqCond4} $\mathbf{E}_i$ and $\mathbf{F}_i$ form a Heisenberg $\mathbf{L}_i$-pair at $d_i\hbar$,
\item\label{EqCond5} $\mathbf{F}_i \star \mathbf{L}_i^{-1}$ is affiliated with $L_{\hbar}(\mathfrak{n})$.
\end{enumerate}
We call a word $\mathbf{i}$ over $I$  \emph{dualizable} if it admits dual simple root operators for each $i\in I$.

\label{DefMUCartan}
The \emph{fundamental Cartan unitary} for the Cartan datum $I$ is defined as the unitary 
\begin{equation}\label{EqCartanMU}
\mathcal{K} := \prod_{i\in I} \overline{e}_{\hbar}\left(\mathbf{H}_i\otimes \mathbf{H}_i'\right) \in L(\mathfrak{h})\bar{\otimes}L(\mathfrak{h}').
\end{equation}

\label{DefFundUnit}
Assume $\mathbf{i}$ is a dualizable word, with associated dual simple root operators $\{\mathbf{F}_i\}$.
The \emph{fundamental braided unitary} associated to $(\mathbf{i},\{\mathbf{F}_i\})$ is
\begin{equation}\label{EqSimpGenMU}
W_{\mathrm{br}} = \prod^{\longrightarrow}_{a\in J} {}^aW_{\mathrm{br}},\qquad {}^aW_{\mathrm{br}} = \overline{F}_{d_{i_a}\hbar}(\mathbf{X}_a \otimes \mathbf{F}_{i_a}) \in L_{\hbar}(\mathfrak{n})\bar{\otimes} L_{\hbar}(\mathfrak{b}') \subseteq L_{\hbar}(\mathfrak{d})\bar{\otimes}L_{\hbar}(\mathfrak{d}),
\end{equation}
where $\prod^{\longrightarrow}_{a\in J}$ means we write out the product from left to right with the index in $J$ increasing.

The \emph{fundamental unitary} associated to $\mathbf{i}$ is 
\begin{equation}\label{EqFundamUnit}
W = W_{\mathrm{br}}\mathcal{K} \in L_{\hbar}(\mathfrak{b})\bar{\otimes}L_{\hbar}(\mathfrak{b}') \subseteq L_{\hbar}(\mathfrak{d})\bar{\otimes}L_{\hbar}(\mathfrak{d}). 
\end{equation}

\label{PropIndepHeis}
Let $W$ be a fundamental unitary for the dualizable word $\mathbf{i}$. Then the unital normal faithful $*$-homomorphism
\[
\Delta: L_{\hbar}(\mathfrak{d}) \rightarrow L_{\hbar}(\mathfrak{d})\bar{\otimes} L_{\hbar}(\mathfrak{d}),\qquad x \mapsto W^*(1\otimes x)W
\]
satisfies 
\begin{equation}\label{EqCoproductRestr}
\Delta(L_{\hbar}(\mathfrak{b})) \subseteq L_{\hbar}(\mathfrak{b})\bar{\otimes}L_{\hbar}(\mathfrak{b})
\end{equation}
and
\begin{equation}\label{EqCrodQUE}
\Delta(\mathbf{K}_i) = \mathbf{K}_i\otimes \mathbf{K}_i,\qquad \Delta(\mathbf{E}_i) =\mathbf{E}_i \otimes 1 \boxplus \mathbf{K}_i\otimes \mathbf{E}_i.
\end{equation}

\label{DefModular}
Let $\mathcal{H},\mathcal{H}'$ be Hilbert spaces and $W \in \mathcal{B}(\mathcal{H}\otimes \mathcal{H}')$ a  unitary. 

We call $W$ \emph{modular} if there exist positive operators $\mathbf{Q}$ on $\mathcal{H}$ and $\hat{\mathbf{Q}}$ on $\mathcal{H}'$, and a (necessarily unique) unitary operator $W_c \in \mathcal{B}(\overline{\mathcal{H}}\otimes \mathcal{H}')$, with $\overline{\mathcal{H}}$ the complex-conjugate Hilbert space to $\mathcal{H}$, such that 
\begin{equation}\label{EqCommModOp}
W^*(\mathbf{Q}\otimes \hat{\mathbf{Q}})W = \mathbf{Q}\otimes \hat{\mathbf{Q}}
\end{equation}
and
\begin{equation}\label{EqLeftInvOp}
\langle \mathbf{Q}\xi\otimes \eta',W(\eta\otimes \xi')\rangle = \langle \overline{\mathbf{Q}\eta}\otimes \eta',W_c(\overline{\xi} \otimes \xi')\rangle,\qquad \forall \xi,\eta\in \mathscr{D}(\mathbf{Q}),\xi',\eta'\in \mathcal{H}'.
\end{equation}
We refer to $\mathbf{Q},\hat{\mathbf{Q}}$ as an associated \emph{modular} and \emph{dual modular} operator.

\label{LemMod}
Let $\mathcal{H},\mathcal{H}',\mathcal{H}''$ be Hilbert spaces, and assume $(V,\mathbf{Q},V_c)$ and $(W,\mathbf{P},W_c)$ satisfy \eqref{EqLeftInvOp} with respect to respectively $\mathcal{H},\mathcal{H}''$ and $\mathcal{H}',\mathcal{H}''$. Then $(U,\mathbf{Q}\otimes \mathbf{P},U_c)$ satisfies \eqref{EqLeftInvOp} with respect to $\mathcal{H}\otimes \mathcal{H}'$ and $\mathcal{H}''$, where 
\begin{equation}\label{EqTensProdMod}
U = V_{13}W_{23} \in \mathcal{B}((\mathcal{H}\otimes \mathcal{H}')\otimes \mathcal{H}''),\qquad U_c = V_{c,13}W_{c,23} \in \mathcal{B}((\overline{\mathcal{H}}\otimes \overline{\mathcal{H}'})\otimes \mathcal{H}'').
\end{equation}

Let $\mathbf{i}$ be a dualizable word, and consider its fundamental unitary $W$, defined in \eqref{EqFundamUnit}, as an element of 
\[
W \in L_{\hbar}(\mathfrak{b}) \bar{\otimes}L_{\hbar}(\mathfrak{b}') \subseteq \mathcal{B}(\widetilde{\mathcal{H}}(\mathbf{i}))\bar{\otimes} L_{\hbar}(\mathfrak{b}') \cong (\mathcal{B}(L^2(\mathbb{R}))^{\bar{\otimes} J}\bar{\otimes} \mathcal{B}(L^2(\mathbb{R}))^{\bar{\otimes} I})\bar{\otimes} L_{\hbar}(\mathfrak{b}'),
\]
using the representation \eqref{EqFaithfRepBor}.  Then we have the identity 
\begin{equation}\label{EqWProdOneSide}
W = \left(\prod^{\longrightarrow}_{a\in J} {}^aW_{a,\bullet}\right)  \left(\prod_{i\in I} \overline{e}_{\hbar}(\mathbf{h}_i\otimes \mathbf{H}_i')\right),
\end{equation}
where
\begin{equation}\label{EqParsToto}
{}^aW = \overline{F}_{d_{i_a}\hbar}(\mathbf{e} \otimes \mathbf{F}_{i_a})\overline{e}_{\hbar}(\mathbf{h} \otimes \mathbf{H}_{\alpha_{i_a}}') \in \mathcal{B}(L^2(\mathbb{R}))\bar{\otimes}L_{\hbar}(\mathfrak{b}'),
\end{equation}
using the notation \eqref{EqBasisGen1}.

A straightforward application of the Gaussian commutation relation \eqref{EqqCommGauss} and the identity \eqref{EqXVar} gives 
\begin{eqnarray*}
\left(\prod^{\longrightarrow}_{a\in J} {}^aW_{a,\bullet}\right)  \left(\prod_{i\in I} \overline{e}_{\hbar}(\mathbf{h}_i\otimes \mathbf{H}_i')\right)&=& W_{\mathrm{br}} \left(\prod_{a\in J} \overline{e}_{\hbar}(\mathbf{h}_a\otimes \mathbf{H}_{\alpha_{i_a}}')\right)\left(\prod_{i\in I} \overline{e}_{\hbar}(\mathbf{h}_i\otimes \mathbf{H}_i')\right)\\
&=& W_{\mathrm{br}}\mathcal{K} \\
&=& W.
\end{eqnarray*}

\label{LemModRank1}
The unitaries ${}^aW$ in \eqref{EqParsToto} are modular, with associated modular operators
\begin{equation}\label{EqRank1Q}
\mathbf{Q} = \mathbf{k}^{-(d_{i_a}+|\hbar|^{-1})},\qquad \hat{\mathbf{Q}} =\mathbf{L}_{i_a}^{1/2}\star \mathbf{L}_{i_a^{\vee}}^{|\hbar|^{-1}/2}.
\end{equation}

\label{TheoModFundMultUni}
Let $\mathbf{i}$ be a dualizable word. Then its fundamental unitary 
\[
W\in \mathcal{B}(\widetilde{\mathcal{H}}(\mathbf{i})\otimes \widetilde{\mathcal{H}}(\mathbf{i}))
\]
is modular, with modular operators given by 
\begin{equation}\label{EqModDatumvN}
\mathbf{Q} = \left(\otimes_{a\in J} \mathbf{k}^{-(d_{i_a}+|\hbar|^{-1})}\right)\otimes \left(\otimes_{i\in I} 1\right),\qquad
\hat{\mathbf{Q}} =\mathbf{L}_{\rho}\star\mathbf{L}_{\rho^{\vee}}^{1/|\hbar|}.
\end{equation}

\label{TheoLeftInvWeight}
Let $V$ be a skew-symmetric space, and assume $V_1,V_2\subseteq V$ are subspaces for which the restricted pairing $\epsilon: V_1\times V_2\rightarrow \mathbb{R}$ is non-degenerate. Let $L_{\hbar}(V) \subseteq \mathcal{B}(\mathcal{H})$ be a faithful normal unital $*$-representation of $L_{\hbar}(V)$, and let 
\[
W \in L_{\hbar}(V_1)\bar{\otimes}L_{\hbar}(V_2)\subseteq \mathcal{B}(\mathcal{H})\bar{\otimes}\mathcal{B}(\mathcal{H})
\]
be a modular unitary.

Then there exists a normal semi-finite weight $\Phi:L_{\hbar}(V)^+ \rightarrow [0,\infty]$ such that 
\begin{enumerate}
\item the normal weight
\begin{equation}\label{EqWeightRest}
\varphi = \Phi_{\mid L_{\hbar}(V_1)^+}: L_{\hbar}(V_1)^+\rightarrow [0,\infty]
\end{equation}
is semi-finite and faithful, and
\item the following left invariance property holds: 
\begin{equation}\label{EqLeftInvGenW}
\Phi((\omega\otimes \operatorname{\mathrm{id}})(\Delta_W(x)) = \varphi(x),\qquad \forall x\in \mathfrak{m}_{\varphi}^+,\omega \in S_*(L_{\hbar}(V)),
\end{equation}
where, viewing $W \in L_{\hbar}(V_1)\bar{\otimes}L_{\hbar}(V_2)\subseteq L_{\hbar}(V)\bar{\otimes}L_{\hbar}(V)$, we put 
\begin{equation}\label{EqConjW}
\Delta_W: L_{\hbar}(V_1) \rightarrow L_{\hbar}(V)\bar{\otimes}L_{\hbar}(V),\qquad x \mapsto  W^*(1\otimes x)W,\qquad x\in L_{\hbar}(V_1).
\end{equation}
\end{enumerate}

\label{DefReflMap}
Let $\mathbf{i}$ be a word over $I$. We define the \emph{reflection map} as the linear map 
\begin{equation}\label{EqReflection}
\varsigma: \mathfrak{b}(\mathbf{i}) \rightarrow \mathfrak{b}(\mathbf{i}),\qquad i \mapsto -i,\qquad a \mapsto a-i_a.
\end{equation}

\label{RefUnitAnti}
There exists a unique unital $*$-anti-isomorphism
\[
R: L_{\hbar}(\mathfrak{b}) \rightarrow L_{\hbar}(\mathfrak{b})
\]
such that 
\begin{equation}\label{EqUnitAntipode}
R(\mathbf{q}(v)) = \mathbf{q}(\varsigma(v)),\qquad \forall v\in \mathfrak{b},
\end{equation}
where $\varsigma$ is the reflection map. Moreover, we then have $R(L_{\hbar}(B)) = L_{\hbar}(B)$, and more precisely
\begin{equation}\label{EqUnitAntipodeForm}
R(\mathbf{K}_i) = \mathbf{K}_i^{-1},\qquad R(\mathbf{E}_i) = \mathbf{E}_i\star\mathbf{K}_i^{-1}.
\end{equation}
In particular, 
\begin{equation}\label{EqOppCopr}
\Delta(R(x)) = (R\otimes R) \Delta^{\mathrm{op}}(x),\qquad x\in L_{\hbar}(B).
\end{equation}

\label{LemAff}
Let $\mathcal{H}$ be a Hilbert space and $M \subseteq \mathcal{B}(\mathcal{H})$ a von Neumann algebra. Assume $\mathbf{A}$ is a positive operator on $\mathcal{H}$. Then 
\begin{equation}\label{EqQExpInM}
\mathbf{A} \,\eta\, M \quad \iff \quad F_{\hbar}(s\mathbf{A}) \in M,\qquad \forall s>0.
\end{equation}

\label{LemStrongCont0}
Let $\mathcal{H}$ be a Hilbert space and $\mathbf{A}$ is a positive operator on $\mathcal{H}$. Then
\begin{equation}\label{EqLimToZero}
  \lim_{t\rightarrow 0} F_{\hbar}(t\mathbf{A}) \rightarrow 0\textrm{ in the
  strong$^*$-topology}.
\end{equation}

Since $\mathbf{X} \,\eta\, M$ and $\mathbf{C} \,\eta\, M$ we have
  \begin{equation*}
    \mathbf{C}^{it}F_{a\hbar}(s\mathbf{X})\mathbf{C}^{-it} \in M, \quad
    \text{for $s > 0$ and $t \in \mathbb{R}$}.
  \end{equation*}
  Hence, making use of \eqref{EqQuantExp},
  \begin{equation}\label{EqPrelimAff}
    \mathbf{C}^{it}F_{a\hbar}(s\mathbf{X})\mathbf{C}^{-it} =
    \mathbf{C}^{it}F_{a\hbar}(s\mathbf{A})F_{a\hbar}(s\mathbf{B})\mathbf{C}^{-it} =
    F_{a\hbar}(sq^{-bit}\mathbf{A})F_{a\hbar}(sq^{-cit}\mathbf{B}) \in M,
  \end{equation}
  where we note that e.g.\ $q^{-bit} = e^{-b\pi  \hbar t} \in
  (0, \infty)$. Writing $s = r q^{bit}$ for some $r > 0$,
   we then find
  \begin{equation*}
    F_{a\hbar}(r\mathbf{A})F_{a\hbar}(rq^{(b-c)it}\mathbf{B}) \in
    M,\quad \text{for all $r > 0$ and $t\in \mathbb{R}$.}
  \end{equation*}
  Taking the limit $t \to -\mathrm{sgn}((b-c)\hbar)\infty$, we find
  by Lemma \ref{LemStrongCont0}   that
  \begin{equation*}
    F_{a\hbar}(r\mathbf{A})\in M \quad \text{for all $r > 0$.}
  \end{equation*}
  Using Lemma \ref{LemAff} we can then conclude that $\mathbf{A}
  \,\eta\, M$. By \eqref{EqPrelimAff}, we get $F_{a\hbar}(s\mathbf{B}) \in M$ for all $s>0$, hence also  $\mathbf{B} \,\eta\, M$.

Write 
  \begin{equation*}
    u = F_{\hbar/2}(\mathbf{A}\star\mathbf{B}^{-1}). 
  \end{equation*}
  By \eqref{EqFormSumId} we get
  \begin{equation*}
    u \mathbf{X} u^* = F_{\hbar/2}(\mathbf{A} \star \mathbf{B}^{-1})(\mathbf{A} \boxplus
    \mathbf{B})F_{\hbar/2}(\mathbf{A} \star \mathbf{B}^{-1})^* = \mathbf{B}.
  \end{equation*}
  Thus, $\mathbf{B} \,\eta\, u M u^*$. Now, since $\mathbf{A} \star \mathbf{B}^{-1}$ and $\mathbf{D}$ strongly 
  commute, we obtain
  \begin{equation*}
    u \mathbf{C} u^* \boxplus \mathbf{D} = u \mathbf{Y} u^* \,\eta\, u M u^*.
  \end{equation*}
  Then, making use of \eqref{EqQuantExp}, we obtain that for all $s>0$
  \begin{equation*}
    F_{\hbar}(s(u \mathbf{C} u^* \boxplus \mathbf{D})) = F_{\hbar/2}(\mathbf{A} \star
    \mathbf{B}^{-1}) F_{ \hbar}(s\mathbf{C})F_{\hbar/2}(\mathbf{A}
    \star\mathbf{B}^{-1})^*F_{\hbar}(s\mathbf{D}) \in u M u^*.
  \end{equation*}
  Using that $\mathbf{B} \,\eta\, u M u^*$ we then find for $t \in \mathbb{R}$ that
  \begin{equation*}
    \mathbf{B}^{it} F_{\hbar}(s(u \mathbf{C} u^* \boxplus \mathbf{D}))\mathbf{B}^{-it}
    = F_{\hbar/2}(q^{-it}\mathbf{A} \star
    \mathbf{B}^{-1}) F_{\hbar}(sq^{it}\mathbf{C})F_{\hbar/2}(q^{-it}\mathbf{A}
    \star\mathbf{B}^{-1})^*F_{\hbar}(sq^{-it}\mathbf{D}) \in u M u^*.
  \end{equation*}
  Taking the limit $t \to \mathrm{sgn}(\hbar)\infty$ after setting $s = r
  q^{-it}$ and using \eqref{EqLimToZero} we find
  \begin{equation*}
    F_{\hbar}(r\mathbf{C}) \in u M u^*\quad \text{for all $r > 0$}.
  \end{equation*}
  Lemma \ref{LemAff} now gives $\mathbf{C} \,\eta\, u M u^*$. This means that also
  \begin{equation*}
    (\mathbf{B}^2 \star \mathbf{C})^{it} F_{\hbar}(s(u \mathbf{C} u^* \boxplus
    \mathbf{D}))(\mathbf{B}^2 \star \mathbf{C})^{-it} \in u M u^*.
  \end{equation*}
  Thus
  \begin{equation*}
    F_{\hbar/2}(\mathbf{A} \star
    \mathbf{B}^{-1}) F_{ \hbar}(sq^{2it}\mathbf{C})F_{\hbar/2}(\mathbf{A}
    \star\mathbf{B}^{-1})^*F_{\hbar}(s\mathbf{D}) \in u M u^*.
  \end{equation*}
  Taking the limit $t \to - \mathrm{sgn}(\hbar)\infty$ and using once again
  \eqref{EqLimToZero} and Lemma \ref{LemAff}, we find that $\mathbf{D} \,\eta\, u M u^*$.
  But $\mathbf{D}$ and $u$ commute, so $\mathbf{D} \,\eta\, M$.

  The rest now follows relatively easily. For $s > 0$ we have, using \eqref{EqQuantExp}, that 
  \begin{equation*}
    F_{ \hbar}(s \mathbf{Y}) = F_{\hbar}(s \mathbf{C})F_{\hbar}(s \mathbf{D}),
  \end{equation*}
   so 
  \begin{equation*}
    F_{ \hbar}(s \mathbf{C}) = F_{\hbar}(s \mathbf{D})^*F_{\hbar}(s \mathbf{Y}) \in M,
  \end{equation*}
  and hence $\mathbf{C} \,\eta\, M$ by Lemma  \ref{LemAff}. Finally, it now follows
  from the first splitting lemma, Lemma \ref{LemSplit1}, that $\mathbf{A} \,\eta\,
  M$ and $\mathbf{B} \,\eta\, M$.

If $\mathbf{i}$ is a word, we write
\begin{equation}
\pi_{\mathfrak{b}}: \mathfrak{d} \twoheadrightarrow \mathfrak{b},\qquad x \mapsto x,\quad y \mapsto 0,\qquad x\in \mathfrak{b},y\in (\mathfrak{b}')^{\perp}
\end{equation}
for the projection onto the first component of \eqref{EqDecompHeis}.

We then define the \emph{left modular vector} $\theta_l$ and \emph{dual left modular vector} $\theta_l^{\vee}$ by  
\begin{equation}
\theta_l = \pi_{\mathfrak{b}}(\rho) \in \mathfrak{b},\qquad \theta_l^{\vee} = \pi_{\mathfrak{b}}(\rho^{\vee}) \in \mathfrak{b}.
\end{equation}

Let $\lambda \in\mathfrak{h}'$. Then
\begin{equation}\label{EqExplicitFormulaProjection}
    \pi_\mathfrak{b} (\lambda) =  -\frac{1}{2}H_{\lambda} + \frac{1}{2} N_{\lambda} \in \mathfrak{b},
\end{equation}
where 
\begin{equation}\label{EqComppi}
H_{\lambda} = \sum_{a \in J}   
    \langle \lambda, \beta_a^{\vee}\rangle i_a,\qquad N_{\lambda} = \sum_{a \in J}\langle \lambda, \beta_a^{\vee}\rangle a.
\end{equation}
Furthermore, recalling the notation \eqref{EqMapToDual}, we have
\begin{equation}\label{EqLambdaAsSumRoots}
\alpha_{H_{\lambda}} = \lambda - w^{-1} \lambda.
\end{equation}

A left invariant nsf weight for $(L_{\hbar}(B),\Delta)$ is given by 
\begin{equation}\label{EqExplicitFormLeftInv}
\varphi = \int_{\widehat{\mathfrak{b}}}^{\hbar,\mathbf{q}(2(\theta_l+|\hbar|^{-1}\theta_l^{\vee}))}.
\end{equation}

\label{LemFormInp}
    We have
    \begin{equation}
        \epsilon(i, \theta_l) = \frac{1}{2}\langle i, \frac{1}{2}(\rho - w^{-1} \rho)\rangle, \quad \epsilon(a,\theta_l)=\frac{1}{2}d_{i_a}, \quad \epsilon(i,\theta_l^{\vee}) = \frac{1}{2}\langle i, \frac{1}{2}(\rho^{\vee} - w^{-1} \rho^{\vee})\rangle, \quad \epsilon(a,\theta_l^{\vee}) = \frac{1}{2}
    \end{equation}
    for all $i \in I$ and $a \in J$.

We have, for $i \in I$, using \eqref{EqExplicitFormulaProjection} and \eqref{EqLambdaAsSumRoots}
    \begin{align*}
        \epsilon(i, \theta_l)
        &= \epsilon(i, \frac{1}{2}\sum_{a \in J} \langle \rho, \beta_a^{\vee}\rangle a)\\
        &= \frac{1}{2}\sum_{a \in J} \langle \rho, \beta_a^{\vee}\rangle \langle i , i_a\rangle /2\\
        &= \frac{1}{2}\langle i,  \frac{1}{2}\sum_{a \in J} \langle \rho, \beta_a^{\vee}\rangle i_a\rangle\\
        &= \frac{1}{2}\langle i, \frac{1}{2}(\rho - w^{-1}\rho)\rangle,
    \end{align*}
    and similarly for $\epsilon(i,\theta_l^{\vee})$.
    On the other hand, for $a \in J$ we have
    \begin{equation*}
        \epsilon(a,\theta_l) = \epsilon(a, \theta_l + (\rho - \theta_l)) = \epsilon(a, \rho) =\frac{1}{2} \langle i_a, \rho \rangle = \frac{1}{2} d_{i_a}.
    \end{equation*}

We define the \emph{right (dual) modular vector} as 
\begin{equation}\label{EqFormRightMod}
\theta_r = \varsigma(\theta_l)\in \mathfrak{b},\qquad \theta_r^{\vee} = \varsigma(\theta_l^{\vee}) \in \mathfrak{b},
\end{equation}
where $\varsigma$ is the reflection map defined in \eqref{EqReflection}.

We have the following explicit formulas for the right (dual) modular vector. 
\begin{equation}\label{EqExplicitFormulaRightModular}
\theta_r = \frac{1}{2}N_{\rho}=  \frac{1}{2}\sum_{a\in J} \langle\rho,\beta_a^{\vee}\rangle a,\qquad \theta_r^{\vee} = \frac{1}{2}N_{\rho^{\vee}}=  \frac{1}{2}\sum_{a\in J} \langle\rho^{\vee},\beta_a^{\vee}\rangle a,
\end{equation}

A right invariant nsf weight for $(L_{\hbar}(B),\Delta)$ is given by 
\begin{equation}\label{EqExplicitFormRightInv}
