First note that if $a \neq c$ and $b \neq d$, that then $W_{ab} W_{cd} = W_{cd} W_{ab}$ as they live in different legs of the tensor product. Without loss of generality let $J = \{1, \dots,N\}$ and $J' = \{1, \dots, M\}$. For $0 \leq k \leq M - 1$ we will show that
    \begin{equation*}
        W = W^{(k)} = (W_{11} \dotsb W_{N1}) \dotsb (W_{1k} \dotsb W_{Nk})(W_{1,k+1} \dotsb W_{1,M}) \dotsb (W_{N,k+1}\dotsb W_{N,M}).
    \end{equation*}
    The case $k = 0$ is true by definition of $W$. To go from $k$ to $k+1$ we proceed as follows. By assumption,
    \begin{equation*}
        W^{(k)} = (W_{11} \dotsb W_{N1}) \dotsb (W_{1k} \dotsb W_{Nk})(W_{1,k+1} \dotsb W_{1,M}) \dotsb (W_{N,k+1}\dotsb W_{N,M}).
    \end{equation*}
    Now note that
    \begin{align*}
        &(W_{1,k+1} \dotsb W_{1,M})(W_{2,k+1}\dotsb W_{2,M}) \dotsb (W_{N,k+1}\dotsb W_{N,M})\\
        &= (W_{1,k+1} W_{2,k+1})(W_{1,k+2}\dotsb W_{1,M})(W_{2,k+2}\dotsb W_{2,M})(W_{3,k+1}\dotsb W_{3,M}) \dotsb (W_{N,k+1}\dotsb W_{N,M})\\
        &= \dots \\
        &= (W_{1,k+1} \dotsb W_{N,k+1}) (W_{1,k+2} \dotsb W_{N,k+2})\dotsb (W_{N,k+2}\dotsb W_{N,M}),
    \end{align*}
    where in each step we bring a term $W_{l,k +1}$ to the front. This is possible because for the terms $W_{ab}$ before it we have $a < l$ and $b > k+1$, so that they commute by our initial observation. We now have
    \begin{align*}
        W^{(k)} 
        &= (W_{11} \dotsb W_{N1}) \dotsb (W_{1k} \dotsb W_{Nk})(W_{1,k+1} \dotsb W_{1,M}) \dotsb (W_{N,k+1}\dotsb W_{N,M})\\
        &= (W_{11} \dotsb W_{N1}) \dotsb (W_{1k} \dotsb W_{Nk})(W_{1,k+1}\dotsb W_{N,k+1})(W_{1,k+2} \dotsb W_{1,M}) \dotsb (W_{N,k+2}\dotsb W_{N,M})\\
        &= W^{(k+1)}.
    \end{align*}
    This completes the proof of the lemma, as
    \begin{align*}
        W^{(M-1)} 
        &= (W_{11} \dotsb W_{N1})\dotsb (W_{1,M-1} \dotsb W_{N,M-1})(W_{1M})\dotsb (W_{NM})\\
        &= (W_{11} \dotsb W_{N1})\dotsb (W_{1,M-1} \dotsb W_{N,M-1})(W_{1M}\dotsb W_{NM})\\
        &= \prod_{b\in J'}^{\longrightarrow}\prod_{a\in J}^{\longrightarrow} W_{ab}.
    \end{align*}

