We need to show the identity 
\[
\varphi_{\hbar}^{(+)}(\mathbf{x} +2\mathbf{p})\varphi_{\hbar}^{(+)}(\mathbf{x}) = \varphi_{\hbar}^{(-)}(\mathbf{x})\varphi_{\hbar}^{(+)}(\mathbf{x}\dotplus 2\mathbf{p})\varphi_{\hbar}(2\mathbf{x}\dotplus 2\mathbf{p})\varphi_{2\hbar}(2\mathbf{x}),
\]
which by \eqref{EqNewDoubl} will follow from 
\begin{equation}\label{EqHolExtArg}
\varphi_{\hbar}^{(+)}(\mathbf{x} +2\mathbf{p})\varphi_{\hbar}^{(-)}(\mathbf{x}) = \varphi_{\hbar}^{(-)}(\mathbf{x})\varphi_{\hbar}^{(+)}(\mathbf{x}\dotplus 2\mathbf{p})\varphi_{\hbar}(2\mathbf{x}\dotplus 2\mathbf{p}).
\end{equation}
But both sides are the continuous boundary values of holomorphic functions 
\begin{equation}\label{EqHolMorph}
z \mapsto \varphi_{\hbar}^{(+)}(\mathbf{x} +2\mathbf{p}+z)\varphi_{\hbar}^{(-)}(\mathbf{x}+z),\qquad z \mapsto \varphi_{\hbar}^{(-)}(\mathbf{x}+z)\varphi_{\hbar}^{(+)}(\mathbf{x}\dotplus 2\mathbf{p}+z)\varphi_{\hbar}(2\mathbf{x}\dotplus 2\mathbf{p}+2z)
\end{equation}
on the strip $\{z\in \mathbb{C}\mid 0< \epsilon \operatorname{\mathrm{Im}}(z) < \pi/2\}$. However, the functions in \eqref{EqHolMorph} also extend continuously to the other boundary of this strip, where with respect to the parameter $z = t+\epsilon \pi i/2$, with $t\in \mathbb{R}$, they become the functions 
\begin{equation}\label{EqHolMorphReal}
t \mapsto \varphi_{\hbar}(\mathbf{x} +2\mathbf{p}+ t + \pi i \epsilon )\varphi_{\hbar}(\mathbf{x}+t)^{-1},\qquad t \mapsto \varphi_{\hbar}(\mathbf{x}+t)^{-1}\varphi_{\hbar}(\mathbf{x}\dotplus 2\mathbf{p}+ t + \pi i \epsilon)\varphi_{\hbar}(2\mathbf{x}\dotplus 2\mathbf{p}+ 2t + \pi i \epsilon).
\end{equation}
Hence \eqref{EqHolExtArg} will follow once we show the identity 
\begin{equation}\label{EqNewId}
\varphi_{\hbar}(\mathbf{x}+t) \varphi_{\hbar}(\mathbf{x} +2\mathbf{p}+ t + \pi i \epsilon )= \varphi_{\hbar}(\mathbf{x}\dotplus 2\mathbf{p}+ t + \pi i \epsilon)\varphi_{\hbar}(2\mathbf{x}\dotplus 2\mathbf{p}+ 2t + \pi i \epsilon)\varphi_{\hbar}(\mathbf{x}+t),\qquad t \in \mathbb{R}.
\end{equation}
But in turn, both sides are boundary values of the holomorphic functions 
\[
z \mapsto \varphi_{\hbar}(\mathbf{x}+t) \varphi_{\hbar}(\mathbf{x} +2\mathbf{p}+ t + z),\qquad z \mapsto \varphi_{\hbar}(\mathbf{x}\dotplus 2\mathbf{p}+ t +z)\varphi_{\hbar}(2\mathbf{x}\dotplus 2\mathbf{p}+ 2t+z)\varphi_{\hbar}(\mathbf{x}+t)
\]
on the strip $\{z\in \mathbb{C}\mid 0< \epsilon \operatorname{\mathrm{Im}}(z) < \pi/2\}$. As the functions coincide on $\mathbb{R}$ by \eqref{EqPentaLog}, they coincide everywhere, proving \eqref{EqNewId} and hence establishing the lemma.

